const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const laSerena = ee.Geometry.Point([-71.2530, -29.9045]); // Coordinates for La Serena, Chile
    const startDate = '2022-07-01';
    const endDate = '2022-08-01'; // Exclusive end date for the month of July

    // 2. Data Acquisition & Check
    const datasetId = 'NASA/GPM_L3/IMERG_V06';
    const bandName = 'precipitationCal';

    let collection = ee.ImageCollection(datasetId)
        .filterBounds(laSerena)
        .filterDate(startDate, endDate)
        .select(bandName);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No images found for the specified period in collection ${datasetId}.`);
        console.log('C1');
        return;
    }

    // 3. Processing
    // GPM data is in mm/hr, with images every 30 minutes (0.5 hours).
    // To get total mm for the month, we sum all images and multiply by the time step (0.5 hours).
    const sumImage = collection.sum();
    const totalPrecipitationMmImage = sumImage.multiply(0.5);

    // 4. Calculation
    // Use a small scale because GPM is a coarse resolution product (0.1 degrees).
    // A single pixel value is sufficient for this point location.
    const precipDict = totalPrecipitationMmImage.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: laSerena,
        scale: 1000, // Scale appropriate for GPM data resolution
        maxPixels: 1e9
    }).get(bandName);

    const totalPrecipitationMm = precipDict.getInfo();

    // 5. Validation & Final Answer
    if (totalPrecipitationMm === null) {
        console.log('Calculation failed: Could not extract precipitation value.');
        console.log('C3');
        return;
    }

    const totalPrecipitationCm = totalPrecipitationMm / 10.0;
    const thresholdCm = 6.0;

    console.log(`GPM images found for July 2022: ${collectionSize}`);
    console.log(`Total rainfall for July 2022: ${totalPrecipitationCm.toFixed(2)} cm`);
    console.log(`Threshold for comparison: ${thresholdCm.toFixed(2)} cm`);

    if (totalPrecipitationCm >= thresholdCm) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
